#!/usr/bin/env node
/* Checks for the 頻度順ドリル bank (src/doushi-drill/data/freq{1,2,3}.js, generated by tools/gen_godan_drill.cjs). */
const fs = require('fs');
const SIMPLIFIED = new Set([...'间问际实验证议务运过见产车单压长关头发汉语纪给结经济应该两动员术业样齐认产权让']);
let bad = 0, total = 0; const hits = []; const all = [];
const flag = (where, s) => { if (typeof s !== 'string') return; const b = [...s].filter(c => SIMPLIFIED.has(c)); if (b.length) hits.push(`  ${where}  ${b.join('')}  →  ${s.slice(0, 50)}`); };
const expect = [215, 210, 200];
for (let i = 1; i <= 3; i++) {
  const arr = new Function(fs.readFileSync(`src/doushi-drill/data/freq${i}.js`, 'utf8') + `;return FQ${i};`)();
  const g = {}; arr.forEach(q => g[q[0]] = (g[q[0]] || 0) + 1);
  const shape = arr.filter(q => q.length !== 8 || q[2].length !== 4 || q[2].some(o => !o) || !q[6]).length;
  const dup = arr.filter(q => new Set(q[2]).size !== 4).length;
  const sorted = arr.every((q, k) => k === 0 || q[0] >= arr[k - 1][0]);
  arr.forEach((q, k) => { flag(`freq${i}#${k + 1} stem`, q[1]); q[2].forEach(o => flag(`freq${i}#${k + 1} option`, o)); });
  const verbs = new Set(arr.map(q => q[4]));
  console.log(`  godan-drill/freq${i}: ${arr.length} items (expect ${expect[i - 1]}), ${verbs.size} verbs, per group ${[1, 2, 3].map(l => g[l] || 0).join('/')}, bad shape ${shape}, dup options ${dup}, grouped ${sorted}`);
  if (arr.length !== expect[i - 1] || shape || dup || !sorted) bad = 1;
  total += arr.length; all.push(...arr);
}
console.log(`  godan-drill: ${total} questions, ${new Set(all.map(q => q[4])).size} distinct verbs`);
if (new Set(all.map(q => q[4])).size !== 100) bad = 1;
const q = (w, f) => all.find(r => r[4] === w && r[1].includes('の' + f + 'は'));
// traps use 1–20 位 verbs only: those have every form; lower bands rotate forms
for (const [w, f, c] of [['行く', 'て形', '行って（いって）'], ['ある', 'ない形', 'ない'], ['入る', 'ない形', '入らない（はいらない）'], ['言う', 'て形', '言って（いって）'], ['持つ', 'た形', '持った（もった）'], ['知る', '可能形', '知れる（しれる）'], ['聞く', '受身形', '聞かれる（きかれる）'], ['出す', '使役受身形', '出させられる（ださせられる）'], ['思う', '意志形', '思おう（おもおう）']]) {
  const r = q(w, f); if (!r || r[2][0] !== c) { console.log(`  TRAP FAIL ${w} ${f}: ${r && r[2][0]}`); bad = 1; } }
if (hits.length) { console.log('MIXED SCRIPT in Japanese fields:'); console.log(hits.join('\n')); bad = 1; } else console.log('  godan-drill mixed-script scan: clean');
process.exit(bad);
